namespace Olca.Tests
{
 using Data=Olca.Application.Management.TrialCustomizationDefinitions;
 public sealed class TrialAbilityV2Tests
 {
  private static CheckpointPlayerDto CaptureDungeonPlayer(PlayerCharacter actor)=>(CheckpointPlayerDto)typeof(DungeonCheckpointSession).Assembly.GetType("Olca.Core.Logic.Dungeon.CheckpointPlayerMapper").GetMethod("CaptureDungeon",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,new object[]{actor});
  private sealed class Store:IClearReturnStore{public ClearReturnProfile Value=new ClearReturnProfile{Customization=Data.NewGameProgress(),OutsideInventory=new OutsideInventoryData{Currency=400}};public bool Fail;public int Writes;public ClearReturnProfile Read(out string error){error=null;return Value.Copy();}public bool TryWrite(long revision,ClearReturnProfile next,out string error){error=null;if(Fail){error="trial ability failure";return false;}Assert.AreEqual(Value.Revision,revision);Value=next.Copy();Writes++;return true;}}
  private static CustomizationProgress PoisonState(int parts){var p=Data.NewGameProgress();p.OwnedAccessoryIds=p.EquippedAccessoryIds=new[]{Data.PoisonAccessoryV2};p.OwnedParts=parts==0?Array.Empty<CustomizationItemCount>():new[]{new CustomizationItemCount{Id=Data.PoisonPartV2,Count=parts}};p.Placements=Enumerable.Range(0,parts).Select(i=>new SavedPartPlacement{InstanceId="p"+i,PartId=Data.PoisonPartV2,X=1+i,Y=1,Rotation=PartRotation.None}).ToArray();return p;}
  [Test] public void 新能力は新IDだけを追加し旧解決DTOと凍結checkpointを変更しない(){var p=Data.NewGameProgress();p.OwnedAccessoryIds=p.EquippedAccessoryIds=new[]{Data.Accessory,Data.QualityAccessory};p.OwnedParts=new[]{new CustomizationItemCount{Id=Data.Part,Count=1}};p.Placements=new[]{new SavedPartPlacement{InstanceId="old",PartId=Data.Part,X=1,Y=1}};var sources=new CustomizationLoadoutSources(Data.CatalogV2(),p);var old=Data.Abilities().Resolve(sources);var actor=new PlayerCharacter(100);actor.SetDepartureAbilities(old);var checkpoint=PortableCheckpointJson.Serialize(CaptureDungeonPlayer(actor));var expanded=Data.AbilitiesV2().Resolve(sources);CollectionAssert.AreEqual(PortableCheckpointJson.Serialize(old.Capture()),PortableCheckpointJson.Serialize(expanded.Capture()));CollectionAssert.AreEqual(checkpoint,PortableCheckpointJson.Serialize(CaptureDungeonPlayer(actor)));Assert.AreEqual(15,expanded.CombineElements(ElementResistances.Neutral).Fire);Assert.AreEqual(1,expanded.RewardQualityBonus);Assert.IsFalse(Data.Abilities().ContainsAccessory(Data.FireAccessoryV2));Assert.IsFalse(Data.Catalog().Accessories.Contains(Data.FireAccessoryV2));}
  [Test] public void 新四品は盤面と能力の両登録がある時だけ旧商品に追加する(){var f=new Olca.Application.Battle.SimpleCardFactory();var settings=new ClearReturnSettings();var old=Data.OutsideShop(Data.Catalog(),Data.AbilitiesV2(),f.CollectionCards,settings);var unsupported=Data.OutsideShop(Data.CatalogV2(),Data.Abilities(),f.CollectionCards,settings);var added=Data.OutsideShop(Data.CatalogV2(),Data.AbilitiesV2(),f.CollectionCards,settings);Assert.AreEqual(7,old.Offers.Count);Assert.AreEqual(11,unsupported.Offers.Count);Assert.AreEqual(16,added.Offers.Count);CollectionAssert.AreEqual(unsupported.Offers.Select(v=>(v.Id,v.Price,v.PurchaseLimit)),added.Offers.Take(11).Select(v=>(v.Id,v.Price,v.PurchaseLimit)));CollectionAssert.AreEqual(new long[]{100,100,60,60},added.Offers.Skip(11).Take(4).Select(v=>v.Price));Assert.IsTrue(added.Offers.Skip(13).Take(2).All(v=>v.PurchaseLimit==0));var state=PoisonState(1);Assert.IsTrue(Data.CanRegister(state));state.BoardId=Data.BoardId;Assert.IsFalse(Data.CanRegister(state));}
  [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)] public void 新能力購入の失敗とcoldは支払所持在庫を保ち装備を自動適用しない(int item){var f=new Olca.Application.Battle.SimpleCardFactory();var shop=Data.OutsideShop(Data.CatalogV2(),Data.AbilitiesV2(),f.CollectionCards,new ClearReturnSettings());var offer=shop.Offers[11+item];var store=new Store();var save=new ClearReturnSession(store);var bytes=PortableCheckpointJson.Serialize(store.Value);store.Fail=true;Assert.IsFalse(save.TryPurchaseOutsideShop(shop,offer.Id,out _));CollectionAssert.AreEqual(bytes,PortableCheckpointJson.Serialize(store.Value));Assert.IsFalse(save.HasPendingSave);store.Fail=false;Assert.IsTrue(save.TryPurchaseOutsideShop(shop,offer.Id,out var error),error);var cold=new ClearReturnSession(store);Assert.AreEqual(400-offer.Price,cold.OutsideInventorySnapshot.Currency);Assert.AreEqual(1,cold.OutsideShopOwnedCount(offer));Assert.IsTrue(Data.CanRegister(cold.CustomizationSnapshot));Assert.IsEmpty(cold.CustomizationSnapshot.EquippedAccessoryIds);Assert.IsEmpty(cold.CustomizationSnapshot.Placements);if(item<2){int writes=store.Writes;Assert.IsFalse(cold.TryPurchaseOutsideShop(shop,offer.Id,out _));Assert.AreEqual(writes,store.Writes);}else{Assert.IsTrue(cold.TryPurchaseOutsideShop(shop,offer.Id,out error),error);Assert.AreEqual(2,cold.OutsideShopOwnedCount(offer));}}
  [TestCase(0,1350)][TestCase(1,1170)][TestCase(2,990)] public void 毒の新能力は付与時の時間だけを加算軽減し既存毒と量間隔を変えない(int parts,int frames){var state=PoisonState(parts);var abilities=Data.AbilitiesV2().Resolve(new CustomizationLoadoutSources(Data.CatalogV2(),state));using(var outside=new OutsideExplorationSession()){var actor=new PlayerCharacter(100);outside.TryInitializePlayer(()=>actor);Assert.IsTrue(outside.TryApplyEquipment(abilities));actor.ApplyPoison("trial278",new StatusEffect(StatusEffectType.Poison,30000,1),600);var poison=actor.CapturePoisons().Single();Assert.AreEqual(frames*50L,poison.RemainingUnits);Assert.AreEqual(1,poison.Damage);Assert.AreEqual(600,poison.IntervalFrames);var restored=OutsidePlayerSaveData.Capture(actor).Restore();Assert.AreEqual(25+parts*10,restored.StatusResistances.Poison);CollectionAssert.AreEqual(PortableCheckpointJson.Serialize(actor.CapturePoisons()),PortableCheckpointJson.Serialize(restored.CapturePoisons()));Assert.IsTrue(outside.TryApplyEquipment(Data.AbilitiesV2().Resolve(new CustomizationLoadoutSources(Data.CatalogV2(),Data.NewGameProgress()))));Assert.AreEqual(frames*50L,actor.CapturePoisons().Single().RemainingUnits);}}
  [Test] public void 新四品の装備保存失敗は旧配置を保持し同計画の再試行とcoldで加算値を復元する(){var f=new Olca.Application.Battle.SimpleCardFactory();var catalog=Data.CatalogV2();var shop=Data.OutsideShop(catalog,Data.AbilitiesV2(),f.CollectionCards,new ClearReturnSettings());var store=new Store();var save=new ClearReturnSession(store);foreach(var offer in shop.Offers.Skip(11).Take(4))Assert.IsTrue(save.TryPurchaseOutsideShop(shop,offer.Id,out _));Assert.IsTrue(save.TryPurchaseOutsideShop(shop,"poison-part-v2",out _));Assert.AreEqual(20,save.OutsideInventorySnapshot.Currency);var placements=new[]{new PartPlacement("fire",Data.FirePartV2,new Vector2Int(1,1)),new PartPlacement("poison1",Data.PoisonPartV2,new Vector2Int(3,1)),new PartPlacement("poison2",Data.PoisonPartV2,new Vector2Int(1,2))};var before=PortableCheckpointJson.Serialize(store.Value);store.Fail=true;Assert.IsFalse(save.TrySetCustomizationLoadout(catalog,new[]{Data.FireAccessoryV2,Data.PoisonAccessoryV2},placements));CollectionAssert.AreEqual(before,PortableCheckpointJson.Serialize(store.Value));Assert.IsTrue(save.HasPendingSave);store.Fail=false;Assert.IsTrue(save.Retry(),save.Error);var cold=new ClearReturnSession(store);Assert.IsTrue(Data.CanRegister(cold.CustomizationSnapshot));var abilities=Data.AbilitiesFor(cold.CustomizationSnapshot).Resolve(new CustomizationLoadoutSources(catalog,cold.CustomizationSnapshot));Assert.AreEqual(30,abilities.CombineElements(ElementResistances.Neutral).Fire);Assert.AreEqual(45,abilities.CombineStatuses(TimedStatusResistances.Neutral).Poison);Assert.AreEqual(3,cold.CustomizationSnapshot.Placements.Length);Assert.AreEqual(20,cold.OutsideInventorySnapshot.Currency);}
  [Test] public void 火の新能力は装飾品と配置パーツを加算して既存の実被害式へ反映する(){var p=Data.NewGameProgress();p.OwnedAccessoryIds=p.EquippedAccessoryIds=new[]{Data.FireAccessoryV2};p.OwnedParts=new[]{new CustomizationItemCount{Id=Data.FirePartV2,Count=1}};p.Placements=new[]{new SavedPartPlacement{InstanceId="fire",PartId=Data.FirePartV2,X=1,Y=1}};var actor=new PlayerCharacter(100);actor.SetDepartureAbilities(Data.AbilitiesV2().Resolve(new CustomizationLoadoutSources(Data.CatalogV2(),p)));Assert.AreEqual(30,actor.Resistances.Fire);actor.TakeDamage(100,attackElement:ElementType.Fire);Assert.AreEqual(30,actor.CurrentHp);}
  [Test] public void 浮遊品はv2両登録に限定し購入失敗と装備保存失敗を非破壊で再試行する(){var f=new Olca.Application.Battle.SimpleCardFactory();var catalog=Data.CatalogV2();var shop=Data.OutsideShop(catalog,Data.AbilitiesV2(),f.CollectionCards,new ClearReturnSettings());Assert.AreEqual(16,shop.Offers.Count);var offer=shop.Offers.Last();Assert.AreEqual("floating-accessory-v2",offer.Id);Assert.AreEqual(200,offer.Price);Assert.AreEqual(1,offer.PurchaseLimit);Assert.IsFalse(Data.Abilities().ContainsAccessory(Data.FloatingAccessoryV2));Assert.IsFalse(Data.Catalog().Accessories.Contains(Data.FloatingAccessoryV2));var store=new Store();var save=new ClearReturnSession(store);var before=PortableCheckpointJson.Serialize(store.Value);store.Fail=true;Assert.IsFalse(save.TryPurchaseOutsideShop(shop,offer.Id,out _));CollectionAssert.AreEqual(before,PortableCheckpointJson.Serialize(store.Value));store.Fail=false;Assert.IsTrue(save.TryPurchaseOutsideShop(shop,offer.Id,out _));Assert.AreEqual(200,save.OutsideInventorySnapshot.Currency);Assert.IsEmpty(save.CustomizationSnapshot.EquippedAccessoryIds);store.Fail=true;Assert.IsFalse(save.TrySetCustomizationLoadout(catalog,new[]{Data.FloatingAccessoryV2},Array.Empty<PartPlacement>()));Assert.IsEmpty(save.CustomizationSnapshot.EquippedAccessoryIds);store.Fail=false;Assert.IsTrue(save.Retry(),save.Error);var cold=new ClearReturnSession(store);Assert.IsTrue(Data.CanRegister(cold.CustomizationSnapshot));var actor=new PlayerCharacter(100);actor.SetDepartureAbilities(Data.AbilitiesFor(cold.CustomizationSnapshot).Resolve(new CustomizationLoadoutSources(catalog,cold.CustomizationSnapshot)));Assert.IsTrue(actor.TerrainState.IsFloating);Assert.IsTrue(OutsidePlayerSaveData.Capture(actor).Restore().TerrainState.IsFloating);Assert.IsFalse(cold.TryPurchaseOutsideShop(shop,offer.Id,out _));var old=cold.CustomizationSnapshot;old.BoardId=Data.BoardId;Assert.IsFalse(Data.CanRegister(old));}
  [TestCase(PanelType.Magma)][TestCase(PanelType.Hole)] public void 試用浮遊装備は探索地形とcheckpoint復元で作用し解除後は既存効果へ戻る(PanelType type){var state=Data.NewGameProgress();state.OwnedAccessoryIds=state.EquippedAccessoryIds=new[]{Data.FloatingAccessoryV2};var map0=DungeonConfig.CreateTestDungeon(20,30,19);var map=new DungeonConfig("float-boundary","仮",20,map0.MapCells,explorationTerrain:new[]{new ExplorationTerrainCell(0,type)});var deck=new Deck();var defs=DungeonCheckpointSession.CreateDefault(map,deck).Definitions;var store=new MemoryCheckpointStore(defs);var session=new DungeonCheckpointSession(defs,store);var actor=new PlayerCharacter(100);actor.SetDepartureAbilities(Data.AbilitiesV2().Resolve(new CustomizationLoadoutSources(Data.CatalogV2(),state)));var game=new DungeonBattleManager(map,actor,deck,new MockRandomProvider(),new MockLogger(),checkpoints:session);game.Dungeon.TickFrame();Assert.AreEqual(100,actor.CurrentHp);Assert.IsFalse(game.Dungeon.IsTerrainRecovering);Assert.IsTrue(CheckpointCodec.TryRestore(PortableCheckpointJson.Decode(PortableCheckpointJson.Encode(store.Read())),defs,out var restored,out var error),error);Assert.IsTrue(restored.Player.TerrainState.IsFloating);using(var outside=new OutsideExplorationSession()){outside.TryInitializePlayer(()=>OutsidePlayerSaveData.Capture(actor).Restore());Assert.IsTrue(outside.TryApplyEquipment(Data.AbilitiesV2().Resolve(new CustomizationLoadoutSources(Data.CatalogV2(),Data.NewGameProgress()))));Assert.IsFalse(outside.Player.TerrainState.IsFloating);var ground=new DungeonBattleManager(map,outside.Player,new Deck(),new MockRandomProvider(),new MockLogger());ground.Dungeon.TickFrame();Assert.AreEqual(type==PanelType.Magma?95:90,outside.Player.CurrentHp);Assert.AreEqual(type==PanelType.Hole,ground.Dungeon.IsTerrainRecovering);}}

 }
}

namespace Olca.Tests
{
 public sealed class TimedAilmentCarryTests
 {
  static void Apply(PlayerCharacter p,bool carry,int frames=120){p.ApplyParalysis(frames,carry);p.ApplyConfusion(frames,carryAcrossBattles:carry);p.ApplyBlindness(frames,carryAcrossBattles:carry);}
  static BattleSystem Battle(PlayerCharacter p,out Enemy enemy){enemy=new Enemy("carry-fixture","仮",1000,ElementType.None,new Vector2Int(4,0));return new BattleSystem(p,new List<Enemy>{enemy},new Deck(),randomProvider:new MockRandomProvider());}
  [TestCase(false)][TestCase(true)] public void 効果ごとの三状態は勝利時に旧解除か明示持越しを選び保存復元で方針を保つ(bool carry){var p=new PlayerCharacter(100);var b=Battle(p,out var e);b.RunLogicalFrame(()=>Apply(p,carry));b.RunLogicalFrame(()=>e.TakeDamage(99999,ElementType.None));Assert.AreEqual(carry,p.CaptureTimedAilments()!=null);var saved=OutsidePlayerSaveData.Capture(p);var cold=PortableCheckpointJson.Deserialize<OutsidePlayerSaveData>(PortableCheckpointJson.Serialize(saved));Assert.AreEqual(saved.Key(),cold.Key());var restored=cold.Restore();Assert.AreEqual(carry,restored.CaptureTimedAilments()!=null);if(carry){var dto=restored.CaptureTimedAilments();Assert.IsTrue(dto.Paralysis.CarryAcrossBattles&&dto.Confusion.CarryAcrossBattles&&dto.Blindness.CarryAcrossBattles);Assert.Greater(dto.Paralysis.RemainingUnits,0);}}
  [TestCase(false,true)][TestCase(true,false)] public void 同種再付与は期間と方針を同じ次frame置換へ送り最新の明示指定を採用する(bool first,bool second){var p=new PlayerCharacter(100);var b=Battle(p,out var e);b.RunLogicalFrame(()=>Apply(p,first));b.RunLogicalFrame(()=>Apply(p,second,60));b.RunLogicalFrame(()=>e.TakeDamage(99999,ElementType.None));Assert.AreEqual(second,p.CaptureTimedAilments()!=null);if(second)Assert.LessOrEqual(p.CaptureTimedAilments().Confusion.RemainingUnits,60*50);}
  [TestCase(false)][TestCase(true)] public void 戦闘破棄は付与予約の方針を保持し解除予約を優先する(bool clear){var p=new PlayerCharacter(100);var b=Battle(p,out _);Apply(p,true);if(clear){p.ClearParalysis();p.ClearConfusion();p.ClearBlindness();}typeof(BattleSystem).GetMethod("AbandonForCheckpoint",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(b,null);var d=p.CaptureTimedAilments();Assert.AreEqual(!clear,d!=null);if(!clear){Assert.IsTrue(d.Paralysis.PendingCarryAcrossBattles);Assert.IsTrue(d.Confusion.PendingCarryAcrossBattles);Assert.IsTrue(d.Blindness.PendingCarryAcrossBattles);var cold=OutsidePlayerSaveData.Capture(p).Restore();CollectionAssert.AreEqual(PortableCheckpointJson.Serialize(d),PortableCheckpointJson.Serialize(cold.CaptureTimedAilments()));}}
  [Test] public void 持越し指定でも期限最終frameと死亡は解除し初回持込みgateは維持する(){var p=new PlayerCharacter(100);var b=Battle(p,out var e);Apply(p,true,1);Assert.Throws<ArgumentException>(()=>OutsideDepartureVitals.Capture(p,false));b.Pause(BattlePauseReason.User);b.TickFrame(17);Assert.IsNotNull(p.CaptureTimedAilments());b.Resume(BattlePauseReason.User);for(int i=0;i<3;i++)b.TickFrame(17);Assert.IsNull(p.CaptureTimedAilments());Apply(p,true);b.RunLogicalFrame(()=>p.TakeDamage(99999));Assert.IsNull(p.CaptureTimedAilments());}
  [Test] public void 旧三状態DTOは新方針なしの同じbytesを維持し壊れた方針は拒否する(){var d=new PlayerTimedAilmentDto{RemainingUnits=50,DisplayFrames=1};Assert.AreEqual("{\"ClearPending\":false,\"DisplayFrames\":1,\"InterruptPending\":false,\"PendingFrames\":null,\"RemainingUnits\":50}",System.Text.Encoding.UTF8.GetString(PortableCheckpointJson.Serialize(d)));d.PendingCarryAcrossBattles=true;Assert.Throws<ArgumentException>(()=>d.Validate());d.PendingCarryAcrossBattles=false;d.RemainingUnits=0;d.CarryAcrossBattles=true;Assert.Throws<ArgumentException>(()=>d.Validate());}
  [Test] public void 持越し状態の出撃checkpointは旧定義へ依存せず時計と方針を復元する(){var map=DungeonConfig.CreateTestDungeon(20,30,19);var deck=new Deck();var definitions=DungeonCheckpointSession.CreateDefault(map,deck).Definitions;var store=new MemoryCheckpointStore(definitions);var session=new DungeonCheckpointSession(definitions,store);var p=new PlayerCharacter(100);Apply(p,true);new DungeonBattleManager(map,p,deck,new MockRandomProvider(),new MockLogger(),checkpoints:session);var bytes=PortableCheckpointJson.Encode(store.Read());Assert.IsTrue(CheckpointCodec.TryRestore(PortableCheckpointJson.Decode(bytes),definitions,out var restored,out var error),error);CollectionAssert.AreEqual(PortableCheckpointJson.Serialize(p.CaptureTimedAilments()),PortableCheckpointJson.Serialize(restored.Player.CaptureTimedAilments()));CollectionAssert.AreEqual(bytes,PortableCheckpointJson.Encode(store.Read()));}
  [Test] public void 持越し試用の新輸送版だけが方針を持ち旧ルートと輸送を変更しない(){var cards=new Olca.Application.Battle.SimpleCardFactory();var catalog=DungeonCheckpointSession.CreateDefault(DungeonConfig.CreateTestDungeon(20,30,19),cards.CreateStarterDeck()).Definitions;var normal=new EnemyPoiseDefinition(30,18,180);var boss=new EnemyPoiseDefinition(60,18,180);var old=Olca.Application.Management.DungeonCoreFactory.CreateTrialStatusRoute(catalog,cards,normal,boss).RouteHash;var route=Olca.Application.Management.DungeonCoreFactory.CreateTrialCarryStatusRoute(catalog,cards,normal,boss);var map=route.CreateInitialMap(0);var value=PortableVisitOption.Capture(map.Visits[0].Options[0]);Assert.AreEqual(6,value.StatusTrial.Length);Assert.IsTrue(PortableCheckpointJson.Deserialize<PortableVisitOption>(PortableCheckpointJson.Serialize(value)).Restore().StatusTrial.CarryAcrossBattles);var legacy=PortableVisitOption.Capture(new DungeonVisitOption("old",new DungeonVisitStatusTrial(60,90,120)));Assert.AreEqual(5,legacy.StatusTrial.Length);Assert.IsFalse(legacy.Restore().StatusTrial.CarryAcrossBattles);Assert.AreEqual(old,Olca.Application.Management.DungeonCoreFactory.CreateTrialStatusRoute(catalog,cards,normal,boss).RouteHash);value.StatusTrial[5]=0;Assert.Throws<ArgumentException>(()=>value.Restore());map.ValidateFinalFloorForDeparture();}
  [Test] public void 初回クリア帰還は持越し方針付き終了状態を採用し再挑戦は入場前個体だけを使う(){var entry=OutsidePlayerSaveData.Capture(new PlayerCharacter(100));var p=new PlayerCharacter(100);var b=Battle(p,out var e);b.RunLogicalFrame(()=>Apply(p,true));b.RunLogicalFrame(()=>e.TakeDamage(99999,ElementType.None));var end=new OutsideClearEndData{EntryLevel=1,Entry=entry,End=OutsidePlayerSaveData.Capture(p).Player};var cold=PortableCheckpointJson.Deserialize<OutsideClearEndData>(PortableCheckpointJson.Serialize(end));var returned=cold.Build("11111111111111111111111111111111",1,new ClearReturnSettings()).Restore();Assert.IsTrue(returned.CaptureTimedAilments().Confusion.CarryAcrossBattles);var retry=new OutsideRetryReturnData{EntryLevel=1,Entry=entry}.Build("11111111111111111111111111111111",1,new ClearReturnSettings()).Restore();Assert.IsNull(retry.CaptureTimedAilments());CollectionAssert.AreEqual(PortableCheckpointJson.Serialize(p.CaptureTimedAilments()),PortableCheckpointJson.Serialize(returned.CaptureTimedAilments()));}

 }
}
